nodes.script:
const parts={all:['全部','五个相互连接的系统','车架承载骑手，车轮负责滚动，传动把踩踏转为后轮扭矩。选择一个系统，观察它如何与整车配合。'],frame:['车架','车架：让各系统成为整车','三角形结构连接车轮、坐垫和转向部件，承受并传递骑手与路面的载荷。图中的位移只是拆解展示。'],wheels:['车轮','车轮：支撑与滚动','轮胎接触地面，轮圈与辐条连接轮毂。前轮随车把转向，后轮接受传动扭矩。'],drive:['传动','传动：把踩踏变为前进','曲柄通过链条驱动后轮。七个可选齿比改变踩踏阻力与每圈前进距离；本示意不精确绘制七片飞轮。'],brakes:['刹车','刹车：用摩擦控制速度','刹把经拉线控制制动机构。这里用简化的轮圈刹车表示，实际走线与装配位置因车型而异。'],cockpit:['操控','操控：把意图传给车辆','车把、把立和前叉组成转向链路，骑手通过车把和刹把控制方向与速度。']};
const nav=document.querySelector('.partnav');for(const [key,p]of Object.entries(parts)){const b=document.createElement('button');b.type='button';b.textContent=p[0];b.dataset.focus=key;b.onclick=()=>DSHUI.setState({focus:key});nav.append(b)}
for(const [key,x]of [['rear',180],['front',540]]){const g=document.querySelector('[data-wheel='+key+']');for(let i=0;i<16;i++){const a=i*Math.PI/8,l=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v]of Object.entries({x1:x,y1:250,x2:x+60*Math.cos(a),y2:250+60*Math.sin(a)}))l.setAttribute(k,v);g.append(l)}}
let current=DSHUI.snapshot,angle=0;
DSHUI.subscribe(s=>{current=s;const e=s.state.explode/100,f=s.state.focus;for(const g of document.querySelectorAll('[data-part]')){const p=g.dataset.part;g.style.opacity=f==='all'||f===p?'1':'.16';if(p==='wheels'){document.getElementById('rearWheel').setAttribute('transform','translate('+(-48*e)+' '+(15*e)+')');document.getElementById('frontWheel').setAttribute('transform','translate('+(48*e)+' '+(15*e)+')')}else{const v={frame:[0,-18],drive:[0,52],brakes:[18,-45],cockpit:[22,-55]}[p];g.setAttribute('transform','translate('+(v[0]*e)+' '+(v[1]*e)+')')}}for(const b of nav.children){b.setAttribute('aria-pressed',String(b.dataset.focus===f));b.disabled=s.disabled}document.getElementById('partTitle').textContent=parts[f][1];document.getElementById('partText').textContent=parts[f][2];document.getElementById('phase').textContent=s.derived.phase;document.getElementById('play').textContent=s.state.playing?'暂停轮转':'播放轮转';document.getElementById('play').disabled=s.disabled});
document.getElementById('play').onclick=()=>DSHUI.setState({playing:!current.state.playing});
DSHUI.animate(({delta})=>{if(current.state.playing&&!current.disabled){angle+=delta*90;for(const [key,x]of [['rear',180],['front',540]])document.querySelector('[data-wheel='+key+']').setAttribute('transform','rotate('+angle+' '+x+' 250)')}});
